def slug(s): return re.sub(r"[^a-z0-9]+","-",s.lower()).strip("-")
out = os.path.join(os.path.dirname(__file__), "..", "data", "kawasan")
for a in A:
    k = a["kawasan"]
    g = {
      "kawasan": k, "negeri": a["negeri"], "daerah": a["daerah"], "dikemaskini": D,
      "ringkasan": ring(k, a["extra"]),
      "tentang": {"tajuk": f"Tentang {k}", "perenggan": a["tentang"]},
      "taman": a["taman"], "pengangkutan": a["pengangkutan"], "pendidikan": a["pendidikan"], "kemudahan": a["kemudahan"],
      "sumber": a["sumber"],
    }
    with open(os.path.join(out, slug(k) + ".json"), "w") as f:
        json.dump(g, f, ensure_ascii=False, indent=2); f.write("\n")
